import{_ as t,o as a,c as r,aj as n}from"./chunks/framework.C6uXqnaX.js";const f=JSON.parse('{"title":"Workspace npm dependencies","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"reference/configs/npm-packages.md","filePath":"reference/configs/npm-packages.md"}'),o={name:"reference/configs/npm-packages.md"};function l(d,e,s,i,c,p){return a(),r("div",null,e[0]||(e[0]=[n('<h1 id="workspace-npm-dependencies" tabindex="-1">Workspace npm dependencies <a class="header-anchor" href="#workspace-npm-dependencies" aria-label="Permalink to &quot;Workspace npm dependencies&quot;">​</a></h1><p>The Angular Framework, Angular CLI, and components used by Angular applications are packaged as <a href="https://docs.npmjs.com/getting-started/what-is-npm" title="What is npm?" target="_blank" rel="noreferrer">npm packages</a> and distributed using the <a href="https://docs.npmjs.com" target="_blank" rel="noreferrer">npm registry</a>.</p><p>You can download and install these npm packages by using the <a href="https://docs.npmjs.com/cli/install" target="_blank" rel="noreferrer">npm CLI client</a>. By default, Angular CLI uses the npm client.</p><div class="tip custom-block"><p class="custom-block-title">HELPFUL</p><p>See <a href="/tools/cli/setup-local" title="Setting up for Local Development">Local Environment Setup</a> for information about the required versions and installation of <code>Node.js</code> and <code>npm</code>.</p></div><p>If you already have projects running on your machine that use other versions of Node.js and npm, consider using <a href="https://github.com/creationix/nvm" target="_blank" rel="noreferrer">nvm</a> to manage the multiple versions of Node.js and npm.</p><h2 id="package-json" tabindex="-1"><code>package.json</code> <a class="header-anchor" href="#package-json" aria-label="Permalink to &quot;`package.json`&quot;">​</a></h2><p><code>npm</code> installs the packages identified in a <a href="https://docs.npmjs.com/files/package.json" target="_blank" rel="noreferrer"><code>package.json</code></a> file.</p><p>The CLI command <code>ng new</code> creates a <code>package.json</code> file when it creates the new workspace. This <code>package.json</code> is used by all projects in the workspace, including the initial application project that is created by the CLI when it creates the workspace. Libraries created with <code>ng generate library</code> will include their own <code>package.json</code> file.</p><p>Initially, this <code>package.json</code> includes <em>a starter set of packages</em>, some of which are required by Angular and others that support common application scenarios. You add packages to <code>package.json</code> as your application evolves.</p><h2 id="default-dependencies" tabindex="-1">Default Dependencies <a class="header-anchor" href="#default-dependencies" aria-label="Permalink to &quot;Default Dependencies&quot;">​</a></h2><p>The following Angular packages are included as dependencies in the default <code>package.json</code> file for a new Angular workspace. For a complete list of Angular packages, see the <a href="/api">API reference</a>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Package name</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/api#angular_common"><code>@angular/common</code></a></td><td style="text-align:left;">The commonly-needed services, pipes, and directives provided by the Angular team.</td></tr><tr><td style="text-align:left;"><code>@angular/compiler</code></td><td style="text-align:left;">Angular&#39;s template compiler. It understands Angular templates and can convert them to code that makes the application run.</td></tr><tr><td style="text-align:left;"><code>@angular/compiler-cli</code></td><td style="text-align:left;">Angular&#39;s compiler which is invoked by the Angular CLI&#39;s <code>ng build</code> and <code>ng serve</code> commands. It processes Angular templates with <code>@angular/compiler</code> inside a standard TypeScript compilation.</td></tr><tr><td style="text-align:left;"><a href="/api#angular_core"><code>@angular/core</code></a></td><td style="text-align:left;">Critical runtime parts of the framework that are needed by every application. Includes all metadata decorators such as <code>@Component</code>, dependency injection, and component lifecycle hooks.</td></tr><tr><td style="text-align:left;"><a href="/api#angular_forms"><code>@angular/forms</code></a></td><td style="text-align:left;">Support for both <a href="/guide/forms">template-driven</a> and <a href="/guide/forms/reactive-forms">reactive forms</a>. See <a href="/guide/forms">Introduction to forms</a>.</td></tr><tr><td style="text-align:left;"><a href="/api#angular_platform-browser"><code>@angular/platform-browser</code></a></td><td style="text-align:left;">Everything DOM and browser related, especially the pieces that help render into the DOM.</td></tr><tr><td style="text-align:left;"><a href="/api#angular_router"><code>@angular/router</code></a></td><td style="text-align:left;">The router module navigates among your application pages when the browser URL changes. For more information, see <a href="/guide/routing">Routing and Navigation</a>.</td></tr><tr><td style="text-align:left;"><a href="https://github.com/angular/angular-cli" target="_blank" rel="noreferrer"><code>@angular/cli</code></a></td><td style="text-align:left;">Contains the Angular CLI binary for running <code>ng</code> commands.</td></tr><tr><td style="text-align:left;"><a href="https://www.npmjs.com/package/@angular/build" target="_blank" rel="noreferrer"><code>@angular/build</code></a></td><td style="text-align:left;">Contains default CLI builders for bundling, testing, and serving Angular applications and libraries.</td></tr><tr><td style="text-align:left;"><a href="https://www.npmjs.com/package/rxjs" target="_blank" rel="noreferrer"><code>rxjs</code></a></td><td style="text-align:left;">A library for reactive programming using <code>Observables</code>.</td></tr><tr><td style="text-align:left;"><a href="https://www.npmjs.com/package/typescript" target="_blank" rel="noreferrer"><code>typescript</code></a></td><td style="text-align:left;">The TypeScript compiler, language server, and built-in type definitions.</td></tr></tbody></table>',12)]))}const m=t(o,[["render",l]]);export{f as __pageData,m as default};
